body.script:
(function () {

  const pageFrame =
    document.getElementById("pageFrame");

  const homeOverlay =
    document.getElementById("homeOverlay");


  /* ===============================
     PAGE SYSTEM
  =============================== */

  function switchPage(page) {

    if (!page) return;


    if (
      page === "home.html" ||
      page === "home"
    ) {

      pageFrame.src =
        "about:blank";

      pageFrame.style.display =
        "none";

      homeOverlay.style.display =
        "flex";

      return;
    }


    homeOverlay.style.display =
      "none";

    pageFrame.style.display =
      "block";

    pageFrame.src =
      page;

  }


  /* BUTTON EVENTS */

  document
    .getElementById("mathButton")
    .addEventListener(
      "click",
      () => switchPage("g.html")
    );


  document
    .getElementById("researchButton")
    .addEventListener(
      "click",
      () => switchPage("b.html")
    );


  document
    .getElementById("settingsButton")
    .addEventListener(
      "click",
      () => switchPage("st.html")
    );


  document
    .getElementById("homeButton")
    .addEventListener(
      "click",
      () => switchPage("home.html")
    );


  document
    .getElementById("calcButton")
    .addEventListener(
      "click",
      () => switchPage("g.html")
    );


  document
    .getElementById("appsButton")
    .addEventListener(
      "click",
      () => switchPage("a.html")
    );


  document
    .getElementById("addButton")
    .addEventListener(
      "click",
      () => switchPage("c.html")
    );


  document
    .getElementById("settingsNavButton")
    .addEventListener(
      "click",
      () => switchPage("st.html")
    );


  /* ===============================
     THEMES
  =============================== */

  const themes = {

    default: {
      accent1: "#9b59b6",
      accent2: "#c084fc",
      bg1: "#000000",
      bg2: "#b700ff"
    },

    girly: {
      accent1: "#ff69b4",
      accent2: "#ffb6d9",
      bg1: "#3a001f",
      bg2: "#ff69b4"
    },

    hacker: {
      accent1: "#00ff55",
      accent2: "#00cc44",
      bg1: "#000800",
      bg2: "#003b15"
    },

    ocean: {
      accent1: "#00aaff",
      accent2: "#66ddff",
      bg1: "#00101f",
      bg2: "#0066aa"
    },

    forest: {
      accent1: "#35c759",
      accent2: "#8bdc8b",
      bg1: "#031007",
      bg2: "#176b2c"
    },

    sunset: {
      accent1: "#ff512f",
      accent2: "#dd2476",
      bg1: "#200000",
      bg2: "#ff512f"
    },

    purple: {
      accent1: "#b026ff",
      accent2: "#d580ff",
      bg1: "#100020",
      bg2: "#6a00a8"
    },

    cyber: {
      accent1: "#ff00cc",
      accent2: "#3333ff",
      bg1: "#08000f",
      bg2: "#330066"
    },

    red: {
      accent1: "#ff2020",
      accent2: "#ff6666",
      bg1: "#120000",
      bg2: "#8b0000"
    },

    midnight: {
      accent1: "#4d6cff",
      accent2: "#7289ff",
      bg1: "#020024",
      bg2: "#090979"
    },

    ice: {
      accent1: "#66e6ff",
      accent2: "#b8f5ff",
      bg1: "#00151c",
      bg2: "#006b7a"
    },

    gold: {
      accent1: "#ffd700",
      accent2: "#fff09a",
      bg1: "#160e00",
      bg2: "#806000"
    },

    cherry: {
      accent1: "#ff1744",
      accent2: "#ff6685",
      bg1: "#180006",
      bg2: "#8b001c"
    },

    lavender: {
      accent1: "#c77dff",
      accent2: "#e0aaff",
      bg1: "#100818",
      bg2: "#5a189a"
    },

    neon: {
      accent1: "#00ffea",
      accent2: "#ff00ff",
      bg1: "#000b12",
      bg2: "#260026"
    },

    coffee: {
      accent1: "#d2691e",
      accent2: "#f4a460",
      bg1: "#100804",
      bg2: "#5c2e0e"
    },

    emerald: {
      accent1: "#00c878",
      accent2: "#63ffb5",
      bg1: "#00140e",
      bg2: "#006b43"
    }

  };


  /* ===============================
     APPLY THEME
  =============================== */

  function applyTheme() {

    let themeName =
      localStorage.getItem(
        "selectedTheme"
      );

    if (
      !themeName ||
      !themes[themeName]
    ) {
      themeName = "default";
    }


    const theme =
      themes[themeName];


    document.documentElement.style
      .setProperty(
        "--accent1",
        theme.accent1
      );


    document.documentElement.style
      .setProperty(
        "--accent2",
        theme.accent2
      );


    document.documentElement.style
      .setProperty(
        "--theme-bg1",
        theme.bg1
      );


    document.documentElement.style
      .setProperty(
        "--theme-bg2",
        theme.bg2
      );

  }


  /* ===============================
     BACKGROUND
  =============================== */

  function applyBackground() {

    const bg =
      document.getElementById("bg");

    if (!bg) return;


    let type =
      localStorage.getItem("bgType");

    let value =
      localStorage.getItem("bgValue");


    if (!type) {

      type = "video";

      value =
        "/background-imgs/OMORILAB ORIGINAL ANIMATION MEME 3333.mp4";

    }


    const oldVideo =
      bg.querySelector(
        ".background-video"
      );

    if (oldVideo) {

      oldVideo.pause();

      oldVideo.remove();

    }


    let themeName =
      localStorage.getItem(
        "selectedTheme"
      ) || "default";


    const theme =
      themes[themeName] ||
      themes.default;


    if (type === "none") {

      bg.style.background =
        `linear-gradient(
          135deg,
          ${theme.bg1},
          ${theme.bg2}
        )`;

      return;

    }


    if (type === "color") {

      bg.style.background =
        value || "#000000";

      return;

    }


    if (type === "image") {

      bg.style.background =
        value
          ? `url("${value}") center/cover no-repeat`
          : "#000000";

      return;

    }


    if (type === "video") {

      if (!value) {

        bg.style.background =
          "#000000";

        return;

      }


      bg.style.background =
        "#000000";


      const video =
        document.createElement(
          "video"
        );


      video.className =
        "background-video";

      video.src =
        value;

      video.autoplay =
        true;

      video.loop =
        true;

      video.muted =
        true;

      video.playsInline =
        true;


      bg.appendChild(
        video
      );


      video.play()
        .catch(() => {});

    }

  }


  /* ===============================
     FIREFLIES
  =============================== */

  function createStars(color) {

    document
      .querySelectorAll(".firefly")
      .forEach(
        star => star.remove()
      );


    for (
      let i = 0;
      i < 90;
      i++
    ) {

      const star =
        document.createElement(
          "div"
        );


      star.className =
        "firefly";


      const size =
        Math.random() * 3 + 1;


      star.style.width =
        size + "px";

      star.style.height =
        size + "px";

      star.style.background =
        color;


      star.style.left =
        Math.random() *
        window.innerWidth +
        "px";


      star.style.top =
        Math.random() *
        window.innerHeight +
        "px";


      const duration =
        Math.random() * 8 + 6;


      star.style.animationDuration =
        duration + "s";


      star.style.animationDelay =
        -(Math.random() * duration) + "s";


      document.body.appendChild(
        star
      );

    }

  }


  /* ===============================
     CLOAK
  =============================== */

  function applyCloakSettings() {

    const title =
      localStorage.getItem(
        "cloakTitle"
      );


    const icon =
      localStorage.getItem(
        "cloakIcon"
      );


    if (title) {

      document.title =
        title;

    }


    if (icon) {

      let link =
        document.querySelector(
          'link[rel="icon"]'
        );


      if (!link) {

        link =
          document.createElement(
            "link"
          );

        link.rel =
          "icon";

        document.head.appendChild(
          link
        );

      }


      link.href =
        icon;

    }

  }


  /* ===============================
     SECRET CODE
  =============================== */

  let secretCode = "";


  document.addEventListener(
    "keydown",
    function(event) {

      if (
        event.key.length !== 1
      ) {
        return;
      }


      secretCode +=
        event.key;


      if (
        secretCode.length > 6
      ) {

        secretCode =
          secretCode.slice(-6);

      }


      if (
        secretCode === "676767"
      ) {

        const secret =
          document.getElementById(
            "secret676767"
          );


        secret.classList.add(
          "active"
        );


        setTimeout(
          () => {

            secret.classList.remove(
              "active"
            );

          },
          2000
        );


        secretCode = "";

      }

    }
  );


  /* ===============================
     START
  =============================== */

  function applySettings() {

    applyTheme();

    applyBackground();

    applyCloakSettings();


    const themeName =
      localStorage.getItem(
        "selectedTheme"
      ) || "default";


    const theme =
      themes[themeName] ||
      themes.default;


    createStars(
      theme.accent2
    );

  }


  window.addEventListener(
    "storage",
    function() {

      applySettings();

    }
  );


  applySettings();


  pageFrame.style.display =
    "none";


  homeOverlay.style.display =
    "flex";

})();
